      }
    ],
    "lacunas": [],
    "motivo": "Término da linha base declarado como D10.",
    "unidade": "dia_corrido"
  },
  "fim_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_6ffaeeffa7",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_d96520b3de",
        "localizador": "L05"
      }
    ],
    "lacunas": [
      "As precedências da ficha relacional d_aa83 não estão disponíveis na view; não é possível calcular o efeito da disponibilidade do substituto sobre o marco final."
    ],
    "motivo": "A disponibilidade do substituto em D6 é informada, mas faltam relações de precedência para determinar o término novo.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_6ffaeeffa7",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_d96520b3de",
        "localizador": "L05"
      }
    ],
    "lacunas": [
      "O término novo não pode ser calculado sem as precedências da ficha relacional d_aa83."
    ],
    "motivo": "A linha base é D10, mas o término após o aviso permanece indeterminado.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 500000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      }
    ],
    "lacunas": [],
    "motivo": "Orçamento de referência declarado de R$ 5.000,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_8ca6cc3cb4",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_6ffaeeffa7",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_e63d1b2e94",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "O preço da extensão, se houver, depende de proposta sem valor ou teto definido; também não é possível determinar pela view se haverá extensão."
    ],
    "motivo": "As parcelas base e a cobrança única de troca são conhecidas, mas o custo eventual de extensão não está quantificado.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {
        "fonte_id": "f_6ffaeeffa7",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_aa2f56bbb7",
        "localizador": "L03"
      }
    ],
    "lacunas": [
      "A magnitude total depende do preço da eventual extensão, ainda sem valor ou teto definido."
    ],
    "motivo": "A troca acrescenta obrigatoriamente R$ 200,00 e não há crédito; eventual extensão tem preço não negativo.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A linha base fornece D10 e R$ 5.000,00. O aviso impõe R$ 200,00 adicionais, mas o custo de eventual extensão não está definido. Sem as precedências da ficha relacional referenciada, não se pode determinar o término novo nem se haverá extensão."
}

